Here's a Python solution for the problem. This program validates the input, handles division by zero, and provides clear error messages for invalid operations.

```python
def get_user_input():
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            operation = input("Enter the operation (+, -, *, /): ")
            num2 = float(input("Enter the second number: "))

            if operation not in ['+', '-', '*', '/']:
                raise ValueError("Invalid operation. Please enter only +, -, *, or /.")

            return num1, operation, num2
        except ValueError as e:
            print(e)

def perform_operation(num1, operation, num2):
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        return num1 / num2
    else:
        return "Invalid operation."

def main():
    try:
        num1, operation, num2 = get_user_input()
        result = perform_operation(num1, operation, num2)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```

This program will keep prompting the user for input until they enter a valid format. It will then perform the specified operation and print the result. If an invalid operation is entered, an error message will be displayed. If division by zero is attempted, an error message will be displayed as well.
